 const root=host.querySelector('.learning-cabinet'),slot=root.querySelector('[data-cabinet-content]'),doc=root.ownerDocument;root.querySelector('[data-refresh-cabinet]').onclick=onRefresh;
 root.addEventListener('click',event=>{const link=event.target.closest?.('a');if(!link||event.defaultPrevented||event.button||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const href=link.getAttribute('href');if(!href?.startsWith('#lesson?'))return;event.preventDefault();onNavigate(href);});
 function action(container,label,run,{secondary=false,disabled=false}={}){const button=doc.createElement('button');button.type='button';button.className='button'+(secondary?' secondary':'');setUiMessage(button,uiMessage(label));button.disabled=disabled;button.onclick=run;container.append(button);return button;}
