export function mountCabinetPupils(root,{lesson,call,onReview=()=>{},isActive=()=>root.isConnected}={}){
 let disposed=false,searchRevision=0;const active=()=>!disposed&&root.isConnected&&isActive();root.innerHTML="<section class=\"cabinet-roster\"><h2>"+uiLeaf("lessonUi.cabinetLessonStudents")+"</h2><p class=\"cabinet-muted\" translate=\"no\" dir=\"auto\">"+esc(lesson.title)+"</p><form class=\"cabinet-student-search\" data-student-search><label>"+uiLeaf("lessonUi.cabinetAddStudent")+"<input name=\"nickname\" "+uiAttribute("lessonUi.cabinetNicknamePlaceholder",{},"placeholder")+" minlength=\"2\" maxlength=\"40\" required autocomplete=\"off\"></label><button type=\"submit\" class=\"button secondary\">"+uiLeaf("lessonUi.cabinetFind")+"</button></form><p class=\"cabinet-muted\">"+uiLeaf("lessonUi.cabinetAccessHelp")+"</p><div data-student-results></div><p role=\"status\">"+uiLeaf("lessonUi.cabinetLoadingStudents")+"</p><div data-pupils></div></section>";const status=root.querySelector('[role=status]'),list=root.querySelector('[data-pupils]'),search=root.querySelector('[data-student-search]'),results=root.querySelector('[data-student-results]');
 search.addEventListener('input',()=>{searchRevision++;results.replaceChildren();});
 search.onsubmit=async event=>{event.preventDefault();const revision=++searchRevision,button=search.querySelector('button');button.disabled=true;results.replaceChildren();try{const value=await call('student-lookup',{id:lesson.id,nickname:search.elements.nickname.value});if(!active()||revision!==searchRevision)return;if(!value.accounts.length){results.innerHTML=uiLeaf('lessonUi.cabinetAccountNotFound');return;}for(const account of value.accounts){const row=root.ownerDocument.createElement('div');row.className='cabinet-student-match';const name=root.ownerDocument.createElement('strong');name.textContent=account.nickname;name.setAttribute('translate','no');name.dir='auto';const add=root.ownerDocument.createElement('button');add.type='button';add.className='lesson-text-button';setUiMessage(add,uiMessage('lessonUi.cabinetAdd'));add.onclick=async()=>{if(!active()||add.disabled)return;add.disabled=true;try{await call('student-add',{id:lesson.id,userId:account.id});if(!active())return;searchRevision++;results.replaceChildren();search.reset();await load();if(active())setUiMessage(status,uiMessage('lessonUi.cabinetStudentAdded'));}catch(error){if(active())setUiMessage(status,lessonErrorMessage(error));}finally{if(add.isConnected)add.disabled=false;}};row.append(name,add);results.append(row);}}catch(error){if(active()&&revision===searchRevision)results.innerHTML=lessonMessageMarkup(error);}finally{if(active())button.disabled=false;}};
 async function load(){try{const result=await call('class-pupils',{id:lesson.id});if(!active())return;list.replaceChildren();setUiMessage(status,result.pupils.length?uiMessage('lessonUi.cabinetAddedCount',{count:result.pupils.length}):uiMessage('lessonUi.cabinetNoStudents'));for(const pupil of result.pupils){const row=root.ownerDocument.createElement('article');row.className='cabinet-pupil';row.innerHTML='<div class="cabinet-pupil-avatar" aria-hidden="true">'+esc((pupil.nickname||'У').slice(0,1).toUpperCase())+'</div><div><h3 translate="no" dir="auto">'+esc(pupil.nickname)+'</h3><p>'+(pupil.workState?workStateMarkup(pupil.workState):uiLeaf(lesson.homework?'lessonUi.cabinetWorkNotSent':'lessonUi.cabinetNoHomeworkAssigned'))+(pupil.readingReview?' · '+uiLeaf('lessonUi.cabinetMistakes',{mistakes:pupil.readingReview.mistakeCount,count:pupil.readingReview.count}):'')+'</p></div>';const actions=root.ownerDocument.createElement('div');actions.className='cabinet-pupil-actions';if(pupil.workState){const button=root.ownerDocument.createElement('button');button.type='button';button.className='lesson-text-button';setUiMessage(button,uiMessage('lessonUi.cabinetReview'));button.onclick=()=>onReview(lesson.id,pupil.id);actions.append(button);}const remove=root.ownerDocument.createElement('button');remove.type='button';remove.className='lesson-text-button';setUiMessage(remove,uiMessage('lessonUi.cabinetRemove'));remove.onclick=async()=>{if(!active()||!window.confirm(t('lessonUi.cabinetRemoveStudent')))return;remove.disabled=true;try{await call('student-remove',{id:lesson.id,userId:pupil.id});if(active())await load();}catch(error){if(active()){setUiMessage(status,lessonErrorMessage(error));remove.disabled=false;}}};actions.append(remove);row.append(actions);list.append(row);}}catch(error){if(active()){setUiMessage(status,lessonErrorMessage(error));const retry=root.ownerDocument.createElement('button');retry.type='button';retry.className='button secondary';setUiMessage(retry,uiMessage('lessonUi.cabinetRetry'));retry.onclick=()=>{retry.remove();void load();};list.replaceChildren(retry);}}}const offLanguage=bindLessonsUi(root);void load();return()=>{disposed=true;offLanguage();searchRevision++;root.replaceChildren();};
}
export function mountCabinetHomework(root,{lesson,call,isActive=()=>root.isConnected,selectedStudent=null}={}){
 let current=lesson,disposed=false,stop=()=>{};const active=()=>!disposed&&root.isConnected&&isActive();root.innerHTML="<section class=\"cabinet-homework\"><nav class=\"cabinet-inline-tabs\" "+uiAttribute("lessonUi.homeworkTitle",{},"aria-label")+"><button type=\"button\" data-task>"+uiLeaf("lessonUi.homeworkTask")+"</button><button type=\"button\" data-works>"+uiLeaf("lessonUi.planStudentWorks")+"</button></nav><div data-content></div></section>";const slot=root.querySelector('[data-content]'),task=root.querySelector('[data-task]'),works=root.querySelector('[data-works]');
 function select(work){stop();slot.replaceChildren();task.setAttribute('aria-pressed',String(!work));works.setAttribute('aria-pressed',String(work));if(work)stop=mountTeacherWork(slot,{lesson:current,call,isActive:active,studentId:selectedStudent});else stop=mountHomeworkEditor(slot,{lesson:current,onCancel:()=>show(),onSave:async(homework,expectedHomeworkRevision)=>{const result=await call('set-homework',{id:current.id,homework,expectedHomeworkRevision});if(!active())return;current=result.lesson;stop();show(uiMessage('lessonUi.cabinetHomeworkSaved'));}});}
 function show(message=''){slot.innerHTML=(message?'<p class="cabinet-notice" role="status">'+lessonMessageMarkup(message)+'</p>':'')+homeworkMarkup(current.homework)+'<button class="button secondary" type="button" data-edit>'+uiLeaf(current.homework?'lessonUi.cabinetEditTask':'lessonUi.cabinetAddTask')+'</button>';slot.querySelector('[data-edit]').onclick=()=>select(false);}
 const offLanguage=bindLessonsUi(root);task.onclick=()=>select(false);works.onclick=()=>select(true);select(Boolean(selectedStudent)||Boolean(current.homework));return()=>{disposed=true;offLanguage();stop();root.replaceChildren();};
}


